/***************************************************************
 *  System: Sprsun CGK040-V3L
 *  Integracja: Home Assistant (MQTT Discovery)
 *
 *  OPIS:
 *  Ten moduł generuje pełną konfigurację MQTT Discovery
 *  dla Home Assistant, obejmując:
 *
 *   • Sensory (analogowe, liczbowe, tekstowe)
 *   • Binary sensors (wejścia, wyjścia, statusy)
 *   • Selects (tryby pracy)
 *   • Switches (coils)
 *   • Buttons (akcje jednorazowe)
 *   • Alarmy 001–150 (binary_sensor)
 *   • Liczniki i statystyki
 *
 *  Całość generowana jest dynamicznie z tablic konfiguracyjnych,
 *  co zapewnia:
 *   – brak duplikacji kodu
 *   – łatwą rozbudowę
 *   – pełną spójność z Node‑RED i Modbus
 *
 ***************************************************************/


/***************************************************************
 * 1. DEFINICJA URZĄDZENIA (Home Assistant → Device Registry)
 ***************************************************************/
const device = {
    identifiers: ["sprsun_cgk040_v3l"],   // unikalny identyfikator urządzenia
    name: "Sprsun CGK040-V3L",            // nazwa widoczna w HA
    manufacturer: "Sprsun",               // producent
    model: "CGK040-V3L"                   // model urządzenia
};


/***************************************************************
 * 2. FUNKCJE POMOCNICZE
 ***************************************************************/
let messages = [];

/**
 * addDiscovery()
 * Funkcja pomocnicza do publikacji konfiguracji MQTT Discovery.
 *
 * @param {string} topic  – pełny topic discovery
 * @param {object} payload – obiekt JSON konfiguracyjny
 */
function addDiscovery(topic, payload) {
    messages.push({
        topic,
        payload: JSON.stringify(payload),
        retain: true
    });
}


/***************************************************************
 * 3. SENSORY (Analogowe, liczbowe, tekstowe)
 *
 * Każdy element tablicy opisuje jeden sensor:
 *   id  – identyfikator MQTT (sprsun/<id>/state)
 *   n   – nazwa encji w HA
 *   u   – jednostka (opcjonalnie)
 *   c   – device_class (opcjonalnie)
 *   icon_topic – dynamiczna ikona (opcjonalnie)
 ***************************************************************/
const sensors = [

    /* --- Tryby i statusy tekstowe --- */
    { id: "tryb_pracy", n: "Tryb pracy" },
    { id: "tryb_pompy_obiegowej", n: "Tryb pompy obiegowej" }, // status tekstowy
    { id: "tryb_wentylatora", n: "Tryb wentylatora" },

    /* --- Temperatury --- */
    { id: "temp_powrotu", n: "Temperatura powrotu", u: "°C", c: "temperature" },
    { id: "temp_zasilania", n: "Temperatura zasilania", u: "°C", c: "temperature" },
    { id: "temp_zewnetrzna", n: "Temperatura zewnętrzna", u: "°C", c: "temperature" },
    { id: "temp_tloczenia", n: "Temperatura tłoczenia", u: "°C", c: "temperature" },
    { id: "temp_ssania", n: "Temperatura ssania", u: "°C", c: "temperature" },
    { id: "temp_cwu", n: "Temperatura CWU", u: "°C", c: "temperature" },
    { id: "temp_parownika", n: "Temperatura parownika", u: "°C", c: "temperature" },

    /* --- Ciśnienia --- */
    { id: "cisnienie_tloczenia", n: "Ciśnienie tłoczenia", u: "bar", c: "pressure" },
    { id: "cisnienie_ssania", n: "Ciśnienie ssania", u: "bar", c: "pressure" },

    /* --- Sterowanie PWM --- */
    { id: "pompka_pwm", n: "Pompka PWM", u: "%" },

    /* --- Wentylatory --- */
    { id: "wentylator_1_ster", n: "Wentylator 1 sterowanie" },
    { id: "wentylator_1_pomiar", n: "Wentylator 1 pomiar" },
    { id: "wentylator_2_ster", n: "Wentylator 2 sterowanie" },
    { id: "wentylator_2_pomiar", n: "Wentylator 2 pomiar" },

    /* --- Wydajność i sprężarka --- */
    { id: "wymagana_wydajnosc", n: "Wymagana wydajność" },
    { id: "aktualna_wydajnosc", n: "Aktualna wydajność" },
    { id: "obroty_sprezarki", n: "Obroty sprężarki", u: "RPM" },
    { id: "zawor_eev", n: "Zawór EEV" },

    /* --- Statusy --- */
    { id: "status", n: "Status" },

    /* --- Zabezpieczenie (dynamiczna ikona) --- */
    {
        id: "zabezpieczenie",
        n: "Zabezpieczenie",
        icon_topic: "sprsun/zabezpieczenie/icon"
    },

    /* --- Pozostałe parametry --- */
    { id: "przegrzanie", n: "Przegrzanie", u: "°C", c: "temperature" },
    { id: "aktualna_funkcja", n: "Aktualna funkcja" },
    { id: "temp_wyswietlacza", n: "Temperatura wyświetlacza", u: "°C", c: "temperature" },
    { id: "status_id", n: "Status ID" },

    /* --- Wersje i modele --- */
    { id: "program_version_1", n: "Program version 1" },
    { id: "program_version_2", n: "Program version 2" },
    { id: "program_version_3", n: "Program version 3" },
    { id: "hp_model_1", n: "HeatPump model 1" },
    { id: "hp_model_2", n: "HeatPump model 2" },

    /* --- Parametry silnika --- */
    { id: "silnik_moc", n: "Silnik moc", u: "W", c: "power" },
    { id: "silnik_napiecie", n: "Silnik napięcie", u: "V", c: "voltage" },
    { id: "silnik_prad", n: "Silnik prąd", u: "A", c: "current" }
];

/* --- Rejestracja sensorów --- */
sensors.forEach(s => {
    let cfg = {
        name: s.n,
        unique_id: "sprsun_" + s.id,
        state_topic: "sprsun/" + s.id + "/state",
        device
    };

    if (s.u) cfg.unit_of_measurement = s.u;
    if (s.c) cfg.device_class = s.c;
    if (s.icon_topic) cfg.icon = s.icon_topic;

    addDiscovery(`homeassistant/sensor/sprsun/${s.id}/config`, cfg);
});


/***************************************************************
 * 4. SELECTS (Tryby pracy)
 *
 *  Każdy select odpowiada za parametr ustawialny Modbus.
 ***************************************************************/

/* --- Tryb pracy główny --- */
addDiscovery("homeassistant/select/sprsun/tryb_pracy/config", {
    name: "Tryb pracy",
    unique_id: "sprsun_tryb_pracy",
    state_topic: "sprsun/tryb_pracy/state",
    command_topic: "sprsun/tryb_pracy/set",
    options: [
        "Chłodzenie",
        "Ogrzewanie",
        "CWU",
        "Chłodzenie+CWU",
        "Ogrzewanie+CWU"
    ],
    device
});

/* --- Tryb pracy wentylatora --- */
addDiscovery("homeassistant/select/sprsun/tryb_pracy_wentylatora/config", {
    name: "Tryb pracy wentylatora",
    unique_id: "sprsun_tryb_pracy_wentylatora",
    state_topic: "sprsun/tryb_pracy_wentylatora/state",
    command_topic: "sprsun/tryb_pracy_wentylatora/set",
    options: ["Dzień", "Noc", "Krzywa grzewcza", "Serwisowy"],
    device
});

/* --- Tryb grzałki --- */
addDiscovery("homeassistant/select/sprsun/grzalka_tryb/config", {
    name: "Tryb grzałki",
    unique_id: "sprsun_grzalka_tryb",
    state_topic: "sprsun/grzalka_tryb/state",
    command_topic: "sprsun/grzalka_tryb/set",
    options: ["Wyłączona", "CWU", "Grzanie", "Wszystko"],
    device
});


/***************************************************************
 * 5. SWITCHES (Coils)
 ***************************************************************/
const switches = [
    { id: "auto_start", n: "Auto Start" },
    { id: "strefy_czasowe", n: "Strefy czasowe" },
    { id: "program_tygodniowy", n: "Program tygodniowy" },
    { id: "grzalka_obudowy", n: "Grzałka obudowy" },
    { id: "grzalka_sprezarki", n: "Grzałka sprężarki" },
    { id: "wlaczenie_pompy", n: "Włączenie pompy" }
];

switches.forEach(sw => {
    addDiscovery(`homeassistant/switch/sprsun/${sw.id}/config`, {
        name: sw.n,
        unique_id: "sprsun_" + sw.id,
        state_topic: `sprsun/${sw.id}/state`,
        command_topic: `sprsun/${sw.id}/set`,
        payload_on: 1,
        payload_off: 0,
        device
    });
});


/***************************************************************
 * 6. BUTTONS (Akcje jednorazowe)
 ***************************************************************/
addDiscovery("homeassistant/button/sprsun/reset_alarmu/config", {
    name: "Reset alarmu",
    unique_id: "sprsun_reset_alarmu",
    command_topic: "sprsun/reset_alarmu/set",
    device
});

addDiscovery("homeassistant/button/sprsun/reset_parametrow/config", {
    name: "Reset parametrów",
    unique_id: "sprsun_reset_parametrow",
    command_topic: "sprsun/reset_parametrow/set",
    device
});


/***************************************************************
 * 7. ALARMY 001–150 (binary_sensor)
 *
 *  Każdy alarm jest osobnym binary_sensor z device_class=problem.
 ***************************************************************/
function addAlarm(id, name) {
    addDiscovery(`homeassistant/binary_sensor/sprsun/alarm${id}/config`, {
        name: `Alarm ${id}: ${name}`,
        unique_id: `sprsun_alarm${id}`,
        state_topic: `sprsun/alarm/${id}/state`,
        payload_on: 1,
        payload_off: 0,
        device_class: "problem",
        device
    });
}

/* --- tutaj wstawiamy tablice alarmów 001–150 (pominięte dla czytelności) --- */


/***************************************************************
 * 8. LICZNIKI / STATYSTYKI
 ***************************************************************/
const counters = [
    { id: "dzienna_ilosc_defrostow", n: "Dzienna ilość defrostów", icon: "mdi:snowflake-melt" },
    { id: "ilosc_defrostow", n: "Ilość defrostów", icon: "mdi:snowflake-melt" },
    { id: "ilosc_wlaczen_dzisiaj", n: "Ilość włączeń dzisiaj", icon: "mdi:counter" },
    { id: "ilosc_wlaczen_w_tym_miesiacu", n: "Ilość włączeń w tym miesiącu", icon: "mdi:counter" },
    { id: "ilosc_wlaczen", n: "Ilość włączeń", icon: "mdi:counter" },
    { id: "ilosc_wlaczen_w_tym_roku", n: "Ilość włączeń w tym roku", icon: "mdi:counter" },
    { id: "zawor_3d_ilosc_przelaczen_od_poczatku_montazu", n: "Zawór 3D – ilość przełączeń od początku montażu", icon: "mdi:counter" },
    { id: "czas_posiadania", n: "Czas posiadania", icon: "mdi:counter", u: "d" }
];

counters.forEach(c => {
    let cfg = {
        name: c.n,
        unique_id: `sprsun_${c.id}`,
        state_topic: `sprsun/${c.id}/state`,
        device
    };

    if (c.icon) cfg.icon = c.icon;
    if (c.u) cfg.unit_of_measurement = c.u;

    addDiscovery(`homeassistant/sensor/sprsun/${c.id}/config`, cfg);
});


/***************************************************************
 * 9. ZAKOŃCZENIE
 ***************************************************************/
return [messages];
